        solution: "using System;\n\nclass Program {\n  static void Main() {\n    int[] scores = { 90, 85, 77 };\n    for (int i = 0; i < scores.Length; i++) {\n      Console.WriteLine(scores[i]);\n    }\n  }\n}",
