        hint: "Use a bool flag set to true right before the break, then check it after the loop to decide whether to print 'All passing'.",
        solution: "using System;\nusing System.Collections.Generic;\n\nclass Program {\n  static void Main() {\n    List<int> scores = new List<int> { 82, 91, 74, 55, 88 };\n    bool foundFailing = false;\n    foreach (int score in scores) {\n      if (score < 60) {\n        Console.WriteLine($\"Stopped at score: {score}\");\n        foundFailing = true;\n        break;\n      }\n    }\n    if (!foundFailing) Console.WriteLine(\"All passing\");\n  }\n}",
