        hint: "class Intern : Employee { public Intern(string name, double baseSalary) : base(name, baseSalary) {} public override double GetPay() { return baseSalary * 0.5; } }",
        solution: "using System;\nusing System.Collections.Generic;\n\ninterface IPayable { double GetPay(); }\n\nabstract class Employee : IPayable {\n  public string Name;\n  protected double baseSalary;\n  public Employee(string name, double baseSalary) {\n    Name = name;\n    this.baseSalary = baseSalary;\n  }\n  public abstract double GetPay();\n}\n\nclass Manager : Employee {\n  private double bonus;\n  public Manager(string name, double baseSalary, double bonus) : base(name, baseSalary) {\n    this.bonus = bonus;\n  }\n  public override double GetPay() { return baseSalary + bonus; }\n}\n\nclass Intern : Employee {\n  public Intern(string name, double baseSalary) : base(name, baseSalary) {}\n  public override double GetPay() { return baseSalary * 0.5; }\n}\n\nclass Program {\n  static void Main() {\n    List<Employee> staff = new List<Employee> {\n      new Manager(\"Ana\", 60000, 10000),\n      new Intern(\"Liza\", 40000),\n    };\n    foreach (Employee e in staff) {\n      Console.WriteLine($\"{e.Name}: {e.GetPay()}\");\n    }\n  }\n}",
